import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易口诀义 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易口诀义 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/011.md","filePath":"zh/classics/koujueyi/011.md"}'),r={name:"zh/classics/koujueyi/011.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>彖曰：小畜，柔得位而上下应之曰「小畜」。健而巽，刚中而志行，乃亨。「密云不雨」，尚往也。「自我西郊」，施未行也。象曰：风行天上，小畜。君子以懿文德。</p><p>初九：复自道，何其咎，吉。</p><p>象曰：「复自道」，其义吉也。</p><p>九二：牵复，吉。</p><p>象曰：牵复在中，亦不自失也。</p><p>九三：舆说辐，夫妻反目。</p><p>象曰：「夫妻反目」，不能正室也。</p><p>六四：有孚，血去惕出，无咎。</p><p>象曰：有孚惕出，上合志也。</p><p>九五：有孚挛如，富以其邻。</p><p>象曰：「有孚挛如」，不独富也。</p><p>上九：既雨既处，尚德载。妇贞厉。月几望，君子征凶。</p><p>象曰：「既雨既处」，德积载也。「君子征凶」，有所疑也。</p><p>解读</p><p>「小畜亨」者，畜谓止积制遏之名。乾阳上进，巽体柔顺，阳气上升，阴不能固，所畜微劣，故曰「小畜」，以阳气得通，故曰「亨」也。「密云不雨，自我西郊」者，阴既微劣，不能止畜于阳，阳气上通，虽复至盛密云而不能施降于雨，但止在西邑之郊而已。亦喻德薄位尊，不能广其恩惠，所化止于一隅也。象曰「风行天上，小畜」者，风谕恩教之义，风既行于天上，即是教化不及于下，故云「小畜象」也。「君子以懿文德」者，懿，美也；化既不行，可以修美，文德之行，待时乃施也。</p><p>「初九，复自道，何其咎，吉」者，复，反也。处畜之初，畜道未盛，往之于四，无所见阂，犹似反归之家，何虑咎害，所以「吉」矣。</p><p>「九二，牵复，吉」，牵，挽相连也。畜道未极，犹可牵挽而进，反复就五，可以吉也。</p><p>「九三，舆说辐，夫妻反目」者，夫小畜之道，先通后畜，至于九三，畜道已成，不可前进，故舆败辐破，难可以行，故「舆说辐」也。三是阳卦之极，上是阴卦之极，阴而制阳，亦犹女之制夫，室家不正，反目相视，故曰「夫妻反目」也。</p><p>「六四有孚，血去惕出，无咎」者，孚，信也；惕，惧也；血，伤也。九三前进，四塞其路，必被侵伤，故称「血」也；畏三侵害，故惕惧也。然则上九处物之极，而恶于三，乃得安其位，不被侵伤，遂得血去而畏惧总除也。</p><p>「九五：有孚挛如，富以其邻」者，二欲上升，而五不相拒也。二牵于五，五又挛二，合信同体，牵挛而行，故曰「有孚挛如」也。五处尊位，富贵昌盛，不独己有，而与于邻，邻谓二也。</p><p>「上九：既雨既处，尚德载。妇贞厉。月几望，君子征凶」者，上九虽是阳爻，而统属阴卦，以上九阴极而致九三之阳，阳不得通，故「既雨」也，不被阳侵而安其位；「既处」也，以阴制阳，是妇制其夫，臣制其君，正之危也，故曰「妇贞厉」。处阴卦之极，积久方显，其犹人之积尚道德，可以运载于下，故曰「尚德载」也。阴之盛极，如月近望以敌日也，故曰「月几望」也。处盛极之地，不可以盈，盈而求进，必见侵伤，故君子之行亦凶，故曰「君子征凶」也。周易口诀义卷一，</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
